require'json';require'fileutils';root=File.expand_path('..',__dir__);output=File.join(root,'docs/generated/logreal01-backend-runtime.json');system('ruby',File.join(root,'tools/analyze_runtime_logs.rb'),'logs/backend-runtime',output)or abort;report=JSON.parse(File.read(output));categories=report.fetch('signatures').map{|row|row.fetch('category')};checks={all_files_scanned:report.dig('summary','files')==2,startup_mapped:categories.include?('startup'),error_signatures_aggregated:report.dig('summary','errorSignatures')==0,diagnostic_only_policy:report.fetch('policy').include?('clues only')};abort("LOGREAL01 failed: #{checks}")unless checks.values.all?
